string read_file(const std::string filename) {
	try {
		std::ifstream ifs(filename, std::ios::binary);
		string txt = std::string((std::istreambuf_iterator<char>(ifs)), (std::istreambuf_iterator<char>()));
		return txt;
	}
	catch (const std::exception& e) {
		return "";
	}
}
