				dialog += "\nadd_text_input|item_name|Name:|" + EditItem[i].Name + "|100|\n";
				dialog += "\nadd_text_input|item_rarity|Rarity:|" + (EditItem[i].rarity != 0 ? to_string(EditItem[i].rarity) : to_string(items[id].rarity)) + "|3|\n";
