				dialog += (items.at(id).blockType == BlockTypes::CLOTHING ? "\nadd_text_input|item_effect|Punch ID:|" + to_string(EditItem[i].Punch_Id) + "|3|\n" : "");
				dialog += "\nadd_spacer|small|\n";
				dialog += "\nadd_label_with_icon|small|`cITEM BUFFS:|left|9436|\n";
				dialog += (items.at(id).blockType == BlockTypes::CLOTHING or items[id].rarity > 0 and items[id].rarity < 999 ? "\nadd_text_input|extra_gems|Extra Gems:|" + to_string(EditItem[i].Gems) + "|3|\nadd_text_input|extra_xp|Extra Xp:|" + to_string(EditItem[i].Xp) + "|3|\n" : "");
				dialog += (items.at(id).blockType == BlockTypes::CLOTHING ? "\nadd_text_input|p_far_range|Punch Far:|" + to_string(EditItem[i].Far_Punch) + "|2|\nadd_text_input|p_hit|Punch Hits:|" + to_string(EditItem[i].Punch_Hit) + "|2|\nadd_text_input|p_place|Place Far:|" + to_string(EditItem[i].Punch_Place) + "|2|\n" : "");
				dialog += "\nadd_textbox|Extra Drops:|left|\nadd_item_picker|itemid|`2Set Extra Drops|Pick items for Extra Drops!|\nadd_text_input|change_bonus|Chance <= (Num):|" + to_string(EditItem[i].Bonus) + "|3|\nadd_smalltext|(Set Extra Items will be dropped when breaking blocks, based on chance.)|\nadd_smalltext|`s'Chance' = rand() % 100 or equal to random 1 to 100 so if you set the number if 'chance' <= <number> (`4descending``) will drop the item.|\ntext_scaling_string|Subscribtions++++++++|\n";
				dialog += (total_ >= 1 ? Extra_ + "\nadd_button_with_icon||END_LIST|noflags|0||\nadd_smalltext|`5(To remove click the item on top)|" : "");
				dialog += (items.at(id).blockType != BlockTypes::CLOTHING ? "\nadd_checkbox|property_gacha|Set Property Gacha|" + to_string(EditItem[i].property_gacha) + "|\nadd_smalltext|`5(If this property is enabled then this '" + items[id].name + "' does not require change to drop items)|\nadd_spacer|small|\n" : "\nadd_spacer|small|");
				dialog += "\nadd_label_with_icon|small|`cITEM PRICING:|left|13812|\n";
				dialog += "\nadd_text_input|item_price|āPrice:|" + to_string(EditItem[i].Item_Price) + "|6|\n";
				dialog += "\nadd_smalltext|(Change it to 0 to remove it from /buy, or add a number to show and sets the price.)|\n";
				dialog += "\nadd_spacer|small|\n";
