	void RedeemCode(ENetPeer* peer) {
		long long time_ = time(nullptr);
		string code_list = "";
		for (int c_ = 0; c_ < redeem_codev2.redeemcode.size(); c_++) {
			if (redeem_codev2.redeemcode[c_].code != "") {
				code_list += "\nadd_custom_textbox|`2Code: " + redeem_codev2.redeemcode[c_].code + " Time: " + (redeem_codev2.redeemcode[c_].time - time_ >= 1 ? Time::Playmod(redeem_codev2.redeemcode[c_].time - time_) : "Expired!") + ", Requiring lvl: " + to_string(redeem_codev2.redeemcode[c_].RequiringLvl) + ", Max Enter: " + to_string(redeem_codev2.redeemcode[c_].MaximumEnter) + "|size:small;|\n";
				if (redeem_codev2.redeemcode[c_].Gemss != 0) code_list += "\nadd_custom_textbox|`2- Gems (x" + setGems(redeem_codev2.redeemcode[c_].Gemss) + ")|size:small;color:255,255,255,255;icon:112;|\n";
				if (redeem_codev2.redeemcode[c_].Prems_Wl != 0) code_list += "\nadd_custom_textbox|`2- Premium Wls (x" + setGems(redeem_codev2.redeemcode[c_].Prems_Wl) + ")|size:small;color:255,255,255,255;icon:244;|\n";
				for (int i_ = 0; i_ < redeem_codev2.redeemcode[c_].items.size(); i_++) {
					code_list += "\nadd_custom_textbox|`2- " + items[redeem_codev2.redeemcode[c_].items[i_].first].name + " (x" + to_string(redeem_codev2.redeemcode[c_].items[i_].second) + ")|size:small;color:255,255,255,255;icon:" + to_string(redeem_codev2.redeemcode[c_].items[i_].first) + ";|\n";
				}
				code_list += "\nembed_data|code|" + redeem_codev2.redeemcode[c_].code + "\nadd_small_font_button|remove_code|            `4REMOVE CODE           |noflags|0|0|\nadd_spacer|small|";
			}
		}
		if (code_list.empty()) code_list = "\nadd_smalltext|None!|left|\n";
		string list = "", str_list = ""; int kiekItemuBus = 0;
		for (int i_ = 0; i_ < pInfo(peer)->r_items.size(); i_++) {
			kiekItemuBus++;
			list += "\nadd_button_with_icon||`$" + items[pInfo(peer)->r_items[i_].first].name + "|staticYellowFrame|" + to_string(pInfo(peer)->r_items[i_].first) + "|" + to_string(pInfo(peer)->r_items[i_].second) + "|\n";
		}
		str_list += "" + (kiekItemuBus >= 1 ? "\ntext_scaling_string|Subscribtions++++++++|" + list + "\nadd_button_with_icon||END_LIST|noflags|0||\n" : "") + "|\n";
		VarList::OnDialogRequest(peer, SetColor() + "set_border_color|0,0,0,255\nset_bg_color|0,0,0,150|\nadd_label_with_icon|big|`wRedeem Code|left|12436|\nadd_spacer|small|\nadd_textbox|`oList of Redeem Code:|left|" + code_list + "|\nadd_spacer|small|\nadd_textbox|`oCreate New Code/Remove Code:|left|\nadd_spacer|small|\nadd_item_picker|itemid|`2Add Items|Pick items for Prize Redeem Code!|\nadd_spacer|small|" + str_list + "\nadd_spacer|small|\nadd_smalltext|`oTime: if you input 1 it is equal to 1 day.|left|\nadd_text_input|Time_Redeem|`oTime:||3|\nadd_custom_textbox|`oLevel Requiring to Claim Code (1-1000):|size:small;|\nadd_text_input|Level_Requi|`oLevel:||5|\nadd_custom_textbox|`oMaximum Player to Claim Code:|size:small;|\nadd_text_input|Maximum_Enter|`oMax:||5|\nadd_text_input|Redeem_CodeV2|`oCode:||10|\nadd_spacer|small|\nadd_custom_textbox|`oAnother Prize:|size:small;|\nadd_checkbox|Redeem_Gems|`oGems|0|\nadd_text_input|Amount_Gems|`oAmount:||10|\nadd_checkbox|Redeem_PremWl|`oPremium Wls|0|\nadd_text_input|Amount_Wls|`oAmount||10|\nend_dialog|set_redeem|Close|Create|\nand_quick_exit|");
	}
