							p.Insert(pInfo(currentPeer)->netID);
							p.Insert("");
							p.Insert("`o" + get_player_nick(currentPeer) + "'s offer.``");
							p.Insert(make_trade_offer(pInfo(currentPeer), true) + "locked|0\nreset_locks|1\naccepted|0");
