void chat_message(ENetPeer* peer, string message) {
	string::difference_type count_of_symbol = std::count(message.begin(), message.end(), '`');
	if (count_of_symbol > 10) return;
	if (visual::has_playmod2(pInfo(peer), 11) || visual::has_playmod(pInfo(peer), "Iron MMMFF")) {
		string msg2 = "";
		for (int i = 0; i < message.length(); i++) {
			if (isspace(message[i])) msg2 += " ";
			else {
				if (isupper(message[i])) msg2 += i % 2 == 0 ? "M" : "F";
				else msg2 += i % 2 == 0 ? "m" : "f";
			}
		}
		message = msg2;
	}
	string check_ = message;
	transform(check_.begin(), check_.end(), check_.begin(), ::tolower);
	{
		string name_ = pInfo(peer)->world;
		vector<World>::iterator p = find_if(worlds.begin(), worlds.end(), [name_](const World& a) { return a.name == name_; });
		if (p != worlds.end()) {
			World* world_ = &worlds[p - worlds.begin()];
			if (world_->world_settings & Re_Ps::SETTINGS_8 and not Role::Moderator(peer) and to_lower(world_->owner_name) != to_lower(pInfo(peer)->tankIDName) and find(world_->admins.begin(), world_->admins.end(), to_lower(pInfo(peer)->tankIDName)) == world_->admins.end()) {
				VarList::OnTalkBubble(peer, pInfo(peer)->netID, "`1(Peasants must not speak)", 0, 1);
				return;
			}
		}
	}
	bool warned = false;
	pInfo(peer)->not_same++;
	if (pInfo(peer)->last_input_text == message) pInfo(peer)->same_input++;
	pInfo(peer)->last_input_text = message;
	if (pInfo(peer)->last_spam_detection + 5500 < (duration_cast<milliseconds>(system_clock::now().time_since_epoch())).count()) pInfo(peer)->last_spam_detection = (duration_cast<milliseconds>(system_clock::now().time_since_epoch())).count(), pInfo(peer)->same_input = 0, pInfo(peer)->not_same = 0;
	if (pInfo(peer)->same_input >= 3 || pInfo(peer)->not_same >= 5) {
		VarList::OnConsoleMessage(peer, "`6>>`4Spam detected! ``Please wait a bit before typing anything else.  Please note, any form of bot/macro/auto-paste will get all your accounts banned, so don't do it!");
	}
	else {
		string chat_color = "`$";
		if (pInfo(peer)->d_name.empty() && pInfo(peer)->tmod == 0) {
			chat_color = Role::Moderator(peer) ? "`5" : "`$";
		}
		if (visual::has_playmod2(pInfo(peer), 28) || pInfo(peer)->hair == 5718) {
			chat_color = "`2";
			if (visual::has_playmod2(pInfo(peer), 28) && rand() % 5 < 1) chat_color += "Brraaiinnss...";
		}
		if (pInfo(peer)->face == 1170) {
			chat_color = "`4";
			replaceAll(message, "w", "v");
		}
		string log = "", chat = "";
		if (check_ != ":/" and check_ != ":p" and check_ != ":*" and check_ != ";)" and check_ != ":d" and check_ != ":o" and check_ != ":'(" and check_ != ":(") {
			log = "CP:_PL:0_OID:_player_chat=" + (chat_color == "`$" ? "" : chat_color) + message;
			for (int i = 0; i < count_of_symbol; i++) log += "``";
			chat = log;
		}
		else chat = message;
		bool bot_chat = false; string bot_text = "";
		if (chat.find("!Pet") != std::string::npos || chat.find("!pet") != std::string::npos) bot_chat = true;
		if (pInfo(peer)->show_pets and bot_chat) {
			for (ENetPeer* currentPeer = server->peers; currentPeer < &server->peers[server->peerCount]; ++currentPeer) {
				if (currentPeer->state != ENET_PEER_STATE_CONNECTED or currentPeer->data == NULL) continue;
				if (pInfo(currentPeer)->world == pInfo(peer)->world) {
					Chat_PetAi chat_pet;
					std::string response = chat_pet.generateResponse(chat);
					VarList::OnTalkBubble(currentPeer, pInfo(peer)->pet_netID, response, 2, 0, 350);
					VarList::OnConsoleMessage(currentPeer, "CP:_PL:0_OID:_CT:[W]_ `6<`w" + pInfo(peer)->pet_name + "`6> " + response, 0, 350);
				}
			}
		}
		for (ENetPeer* currentPeer = server->peers; currentPeer < &server->peers[server->peerCount]; ++currentPeer) {
			if (currentPeer->state != ENET_PEER_STATE_CONNECTED or currentPeer->data == NULL) continue;
			if (pInfo(currentPeer)->world == pInfo(peer)->world) {
				if (find(pInfo(currentPeer)->ignored.begin(), pInfo(currentPeer)->ignored.end(), to_lower(pInfo(peer)->tankIDName)) == pInfo(currentPeer)->ignored.end()) {
					if (not pInfo(currentPeer)->cheat_hidechat) {
						VarList::OnTalkBubble(currentPeer, pInfo(peer)->netID, chat, 0, 0);
						VarList::OnConsoleMessage(currentPeer, "CP:_PL:0_OID:_CT:[W]_ `6<`w" + (get_player_nick(peer)) + "`6> " + chat_color + message);
					}
				}
			}
		}
	}
}
unsigned long createRGB(int r, int g, int b) {
	return ((r & 0xff) << 16) + ((g & 0xff) << 8) + (b & 0xff);
}
