							if (items[item].petAbility == "") {
								variants::on_bubble(p_, pInfo(p_)->netID, "A " + items[item].name + " would not make a very good Battle Pet.", 0, 0);
								break;
							}
							if (item < 0 or item > items.size()) break;
							World* world_ = &worlds[p - worlds.begin()];
